    expect(tab('Project').classList.contains('active')).toBe(true)
    expect(tab('Models').classList.contains('active')).toBe(false)
    app.remove()
  })

  it('a_saved_setting_is_posted_to_the_host_with_its_key', () => {
    posted.length = 0
